    generic_affine_v: OutputPathType | None = None
    inverse_warped_v: OutputPathType | None = None
    inverse_warp_v: OutputPathType | None = None
    warped_v: OutputPathType | None = None
    warp_v: OutputPathType | None = None
    root_v: OutputPathType = execution.output_file(".")
    __v0 = params.get("output")
